        ('10064348', 'g_invalidRectCount', 'data', 'dirtyrect', "Count compared with 0x63 (=MAX_INVALID_RECTS-1) in 10022151, zeroed by 1002241c; Jupiter 'uint32 g_invalidRectCount'.", 'high', 'jupiter'),
        ('10022151', 'InvalidateRect', 'func', 'dirtyrect', 'Line-for-line Jupiter dirtyrect.cpp InvalidateRect(LTRect*): NULL = whole screen (0,0,g_ScreenWidth 10057e34,g_ScreenHeight 10057f28, count 1), contains test, best-merge by area (RectangleCombine), count>=99 -> whole screen.', 'high', 'jupiter'),
        ('100222c0', 'RectangleCombine', 'func', 'dirtyrect', 'Component-wise min(left,top)/max(right,bottom) of two RECTs = Jupiter inline RectangleCombine, here out of line (called twice from InvalidateRect).', 'high', 'jupiter'),
        ('1002231c', 'guess_DirtyRectSwap_Windowed', 'func', 'dirtyrect', 'GetClientRect+ClientToScreen on the window, then per dirty rect IDirectDrawSurface7::Blt (slot 0x14, DDBLT_WAIT 0x1000000) from g_pOffscreen DAT_1005781c to the primary g_pPrimary at the client offset, then count=0; called only from 100223c8.', 'low', 'invented'),
        ('100223c8', 'DirtyRectSwap', 'func', 'dirtyrect', 'Called from d3d_SwapBuffers (1001e189); no-op if g_invalidRectCount==0, windowed path -> 1002231c else Blts each dirty rect from g_pOffscreen to the back buffer g_pBackBuffer; Jupiter dirtyrect.cpp DirtyRectSwap (copies dirty rects to the front buffer).', 'high', 'jupiter'),
        ('1002241c', 'ClearDirtyRects', 'func', 'dirtyrect', 'Body is just g_invalidRectCount = 0; called from d3d_SwapBuffers next to DirtyRectSwap; Jupiter ClearDirtyRects.', 'high', 'jupiter'),
        ('10057e34', 'g_ScreenWidth', 'data', 'dirtyrect', "InvalidateRect(NULL) uses it as right edge, 'Width: %d Height: %d' message prints it; Jupiter common_stuff.h g_ScreenWidth.", 'medium', 'jupiter'),
        ('10057f28', 'g_ScreenHeight', 'data', 'dirtyrect', 'InvalidateRect(NULL) uses it as bottom edge (written together with g_ScreenWidth at 12136); Jupiter g_ScreenHeight.', 'medium', 'jupiter'),
        ('10064370', 'g_CanvasDrawMgr', 'data', 'draw_canvas', "Object built by static init 10022424 -> ctor 1002244d (vtable 100463c8 = ILTCustomDraw slots); passed as first arg 'pDraw' of Canvas::m_Fn (CanvasDrawFn(ILTCustomDraw*,obj,user)); Jupiter draw_canvas.cpp 'CanvasDrawMgr g_CanvasDrawMgr'.", 'medium', 'jupiter'),
        ('100463c8', 'CanvasDrawMgr::vftable', 'vtable', 'draw_canvas', '5 slots = sdk iltcustomdraw.h ILTCustomDraw order: DrawPrimitive 100226e9, SetState 10022832, GetState 100229d5, SetTexture 100229f2, GetTexelSize 10022a73 (no dtor slot).', 'medium', 'vtable'),
        ('1002244d', 'CanvasDrawMgr::CanvasDrawMgr', 'func', 'draw_canvas', 'Sets vtable 100463c8, memset(this+0x2c,0,0x20) (the 8 LTRState values), this+0x28=0; only caller is static init 10022424 for g_CanvasDrawMgr.', 'medium', 'jupiter'),
        ('1002246e', 'CanvasDrawMgr::DrawCanvas', 'func', 'draw_canvas', 'if (canvas->m_Fn (+0x1b0)) { restore/apply states; m_Fn(this, canvas, canvas->m_pFnUserData (+0x1b4)); restore } = Jupiter CanvasDrawMgr::DrawCanvas(Canvas*) (Canvas::m_Fn at 0x1b0 per de_objects.h).', 'medium', 'jupiter'),
        ('100224ae', 'guess_CanvasDrawMgr::SaveAndSetDefaultStates', 'func', 'draw_canvas', 'Gets (slot 0x54/0x90) then sets the sdk iltcustomdraw.h defaults: ALPHABLENDENABLE(0x1b)=0, ZENABLE(7)=1, ZWRITEENABLE(0xe)=1, SRCBLEND(0x13)=5, DESTBLEND(0x14)=6, TSS stage0 ADDRESS(0xc)=1, COLOROP(1), ALPHAOP(4); stores the shadow copies at this+0x2c.. (LTRState[8]).', 'low', 'invented'),
        ('10022645', 'guess_CanvasDrawMgr::RestoreStates', 'func', 'draw_canvas', 'Re-sets ALPHABLEND/ZENABLE/ZWRITE/SRCBLEND/DESTBLEND/FOGENABLE and stage0 ADDRESS/COLOROP/ALPHAOP from the values saved by 100224ae (this+4..+0x24).', 'low', 'invented'),
        ('100226e9', 'CanvasDrawMgr::DrawPrimitive', 'func', 'draw_canvas', 'Slot 0 of ILTCustomDraw (pVerts,nVerts,flags): returns 1 if nVerts<3, clips (1000af16) / transforms (10008719,100062e0) and DrawPrimitive(D3DPT_TRIANGLEFAN=6, FVF 0x1c4=D3DFVF_TLVERTEX, ...) via device slot 0x64; flags&0x40 selects the really-close path.', 'medium', 'vtable'),
        ('10022803', 'guess_LTBlendToD3DBlend', 'func', 'draw_canvas', 'Maps LTBLEND_* (iltcustomdraw.h: ZERO1 ONE2 SRCCOLOR3 INVSRCCOLOR4 SRCALPHA5 INVSRCALPHA6) to D3DBLEND, default 2; used by SetState for SRCBLEND/DESTBLEND.', 'low', 'invented'),
        ('10022832', 'CanvasDrawMgr::SetState', 'func', 'draw_canvas', 'Slot 1: switch on LTRState 0..7 -> RS 0x1b/7/0xe/0x13/0x14 and TSS(0,0xc / 1 / 4); stores value at this+0x2c+4*state, returns 1 for state>=8 (NUM_LTRSTATES).', 'medium', 'vtable'),
        ('10022990', 'guess_LTTexAddrToD3DTADDRESS', 'func', 'draw_canvas', 'Compiler-fused if chain: LTTEXADDR_WRAP(1)->1, LTTEXADDR_CLAMP(2)->3 (D3DTADDRESS_CLAMP), default 1; used by SetState case 5.', 'low', 'invented'),
        ('100229a8', 'guess_LTOpToD3DTOP', 'func', 'draw_canvas', 'Fused if chain LTOP_* (1..5) -> D3DTOP 2/3/4/7/8, default 7; used by SetState cases 6/7.', 'low', 'invented'),
        ('100229d5', 'CanvasDrawMgr::GetState', 'func', 'draw_canvas', 'Slot 2: if state<8 *out = this[0x2c+4*state]; returns state>=8 (error flag).', 'medium', 'vtable'),
        ('100229f2', 'CanvasDrawMgr::SetTexture', 'func', 'draw_canvas', 'Slot 3 (const char*): NULL -> d3d_DisableTexture(stage); else g_pStruct->GetSharedTexture(name) (slot +4), bind via 100079e4, apply SharedTexture::m_pStateChange (+0x34) through 10021db7.', 'medium', 'vtable'),
        ('10022a73', 'CanvasDrawMgr::GetTexelSize', 'func', 'draw_canvas', 'Slot 4 (float&,float&): copies DAT_10061810/DAT_10061814 (texel size of the currently bound texture).', 'medium', 'vtable'),
        ('10022a90', 'd3d_DrawCanvasCB', 'func', 'draw_canvas', '(Params, LTObject*) -> g_CanvasDrawMgr.DrawCanvas(obj) (1002246e on 10064370); Jupiter d3d_DrawCanvasCB is identical; used as DrawObjectFn by 10022ae3/10022b3b.', 'high', 'jupiter'),
        ('10022a9f', 'd3d_ProcessCanvas', 'func', 'draw_canvas', 'g_ObjectHandlers[OT_CANVAS=10].m_ProcessObjectFn (1004bb50); d3d_GetVisibleSet()+0x2e4 (VS_CANVASES, Init offset 0x2e4) .Add(obj); Talon does not split solid/translucent here.', 'high', 'jupiter'),
        ('10022ab6', 'BaseObjectSet::Add', 'func', 'tagnodes', 'Out-of-line copy of tagnodes.h BaseObjectSet::Add: if m_nObjects(+4) < m_nMaxObjects(+0x14) store obj else AddDebugMessage(1,"Set \'%s\' overflowed") (string 1004b974).', 'high', 'string'),
        ('10022ae3', 'd3d_DrawSolidCanvases', 'func', 'draw_canvas', 'If g_CV_DrawCanvases (10064350): partitions VisibleSet canvas set (+0x2e4) via 10022b50, solid ones drawn with d3d_DrawCanvasCB, translucent ones appended to the set at +0x304 (VS_CANVASES_TRANSLUCENT); first canvas draw step in d3d_FlushObjectQueues (after polygrids) like Jupiter d3d_DrawSolidCanvases.', 'medium', 'jupiter'),
        ('10022b15', 'd3d_QueueTranslucentCanvases', 'func', 'draw_canvas', 'If DrawCanvases: BaseObjectSet::Draw(set +0x304 = VS_CANVASES_TRANSLUCENT, Params, 10022b3b) which adds each to the sorted list; position in d3d_FlushObjectQueues matches Jupiter (after QueueTranslucentModels, before sprites).', 'high', 'jupiter'),
        ('10022b3b', 'guess_d3d_QueueCanvasThunk', 'func', 'draw_canvas', "(Params,obj) -> ObjectDrawList::Add(g_pTransObjList 1006b934, obj, d3d_DrawCanvasCB); Talon open-codes Jupiter's BaseObjectSet::Queue per object type.", 'low', 'invented'),
        ('10022b50', 'guess_DrawCanvasSetSplitSolidTranslucent', 'func', 'draw_canvas', 'Per canvas in set: visibility test on m_Flags(+0x88)/m_Flags2, then if Canvas client flags (+0x188) & 0x10 (CF_SOLIDCANVAS, ltcodes.h) call fn(Params,obj) else BaseObjectSet::Add on the translucent set (10022ab6).', 'low', 'invented'),
        ('10056274', 'guess_g_ClipPlaneMask', 'data', '', 'Set to 0x3f before clipping (100226e9, 10025078), saved/restored per queued poly (1002362a: g_ClipFlags=bucket[3]) and passed to 100264ad whose bits 1,2,4,8,0x10,0x20 each select one of six plane clippers.', 'low', 'invented'),
        ('10055cf8', 'g_ViewParams', 'data', 'common_stuff', "Passed as 'const ViewParams& Params' to every d3d_Draw*/Queue* callback (10022ae3, 10023cb0, 10024d22, 100298b6, 10028660 ...); m_Pos read at +0x4b4..+0x4bc by the distance code in 100289b0 (Jupiter CalcDistance); Jupiter common_stuff.h g_ViewParams.", 'medium', 'jupiter'),
        ('10022be4', 'guess_QueuePolyForDraw', 'func', '', 'FUN_10007ddb(poly,&DAT_10058c90,1) (append to per-owner poly list head 10058c90) then stores the clip-plane mask g_ClipFlags in the new node (+0xc); the list is drained by 100235e2.', 'low', 'invented'),
        ('10022c01', 'guess_DrawPolyMultipassGouraud', 'func', '', "Poly (0x54/0x56 vertex count, <=0x80 else 'Error: vertex buffer overflow' 1004842c) converted by 1002329f/1002331b, clipped (1000af16), DrawPrimitive fan (type 6, FVF 0x1c4) with blend states; uses g_CV_MultipassGouraud (10065bc0) in the caller 1002362a; calls the dynamic-light pass 10022f85 when poly+0x30 list non-empty and LMDynamic (10076788).", 'low', 'invented'),
        ('10022f85', 'guess_DrawPolyDynamicLightPass', 'func', '', 'For each dynamic light linked to the poly (list at poly+0x30, light radius via vcall +0x38) computes per-vertex UV = (dot(v-lightpos, axis)*1/r)+0.5 and draws the poly again additively (ALPHABLENDENABLE=1, SRCBLEND=DESTBLEND=D3DBLEND_ONE, FOGCOLOR=0, saving/restoring them); called only from 10022c01 when LMDynamic is on.', 'low', 'invented'),
        ('1002329f', 'guess_BuildPolyVertices_Opaque', 'func', '', "Fills 0x20-byte D3DTLVERTEX-style verts (x,y,z + colour bytes at +0x10..+0x13 via 256-entry LUTs DAT_10059d04/59e04/59f04, tu,tv at +0x18/+0x1c) from the poly's 0x18-byte vertex list.", 'low', 'invented'),
        ('1002331b', 'guess_BuildPolyVertices_Translucent', 'func', '', 'Same as 1002329f but with the second LUT set DAT_1005a004/5a104/5a204 (translucent/alt colour tables).', 'low', 'invented'),
        ('10023398', 'guess_DrawPolyGouraud', 'func', '', "Single-pass gouraud/textured poly: builds verts (1002329f), clips (1000af16), scales UVs by current texel size (1002358b), DrawPrimitive fan; falls to 10022c01 when poly has dynamic lights and LMDynamic; 'vertex buffer overflow' guard at 0x81 verts.", 'low', 'invented'),
        ('1002358b', 'guess_ScalePolyUVByTexelSize', 'func', '', 'Multiplies each vertex tu,tv (+0x18,+0x1c) by DAT_10061810/DAT_10061814 (texel size of bound texture).', 'low', 'invented'),
        ('100235e2', 'guess_FlushQueuedPolys', 'func', '', "Walks bucket list DAT_10058c90, calls 1002362a per bucket, clears the owner's pointer (+0x20) and returns the bucket to pool free list DAT_10058cb0.", 'low', 'invented'),
        ('1002362a', 'guess_FlushPolyBucket', 'func', '', 'Per queued poly: restores g_ClipFlags from the node, then dispatches to 10022c01 (MultipassGouraud on) or 10023398/100236ae/10023763 depending on texture caps; returns node to pool DAT_10058770.', 'low', 'invented'),
        ('10023860', 'd3d_ProcessLight', 'func', 'drawlight', "g_ObjectHandlers[OT_LIGHT=4].m_ProcessObjectFn (1004bad8); if g_DynamicLight (1004875c) VisibleSet+0x244 (VS_LIGHTS) Add(obj) with inlined 'Set '%s' overflowed' check.", 'high', 'jupiter'),
        ('100238b0', 'guess_AddDynamicLightToWorldModelPolys', 'func', 'drawlight', 'Walks a BSP/node list testing |dot(light pos,plane)-d| <= light radius (light+0x1b0) and sphere distance, allocates link nodes from pools DAT_10056220/10056240 and attaches the light to Node/poly list at +0x30 (the list read by 10022f85); only called through 10023b00.', 'low', 'invented'),
        ('10023b00', 'guess_WorldModelLightCB', 'func', 'drawlight', 'Callback (obj,...): if obj->m_ObjectType(+0xbc)==OT_WORLDMODEL(2) call 100238b0; used as FindObjInfo callback by 10023b20 (same role as Jupiter ModelDraw::StaticLightCB(WorldTreeObj*,void*)).', 'low', 'invented'),
        ('10023b20', 'guess_d3d_ProcessVisibleLightCB', 'func', 'drawlight', "Per light of VS_LIGHTS: appends to visible-light array DAT_100566d0 (max 0x28, count DAT_10056218) and, unless flag 0x80, queries world models in the light's box via the world BSP client (DAT_10056770 vcall +8) with callback 10023b00.", 'low', 'invented'),
        ('10023cb0', 'guess_d3d_ProcessVisibleLights', 'func', 'drawlight', 'If g_DynamicLight: BaseObjectSet::Draw(VisibleSet+0x244 lights set, g_ViewParams, 10023b20); sole caller is 10039540 (tagnodes region, after leaf tagging).', 'low', 'invented'),
        ('10023ce0', 'd3d_ProcessLineSystem', 'func', 'drawlinesystem', 'g_ObjectHandlers[OT_LINESYSTEM=8].m_ProcessObjectFn (1004bb28); VisibleSet+0x2a4 (VS_LINESYSTEMS) Add(obj) with inlined overflow message.', 'high', 'jupiter'),
        ('10023d30', 'd3d_QueueLineSystems', 'func', 'drawlinesystem', 'If g_DrawLineSystems (1004877c) and the line-system set (+0x2a4) non-empty: BaseObjectSet::Draw(set,Params,10023d60) which Adds each to the sorted list; position in d3d_FlushObjectQueues = Jupiter order (after polygrids, before worldmodels).', 'high', 'jupiter'),
        ('10023d60', 'guess_d3d_QueueLineSystemThunk', 'func', 'drawlinesystem', '(Params,obj) -> ObjectDrawList::Add(g_pTransObjList, obj, 10023d80).', 'low', 'invented'),
        ('10023d80', 'd3d_DrawLineSystem', 'func', 'drawlinesystem', 'Draw callback for a LineSystem object: FOGENABLE off (if g_FogEnable), unbind texture, builds two 0x20-byte TL verts per LSLine (colour floats*255, alpha*obj alpha +0x97) and DrawPrimitive(D3DPT_LINELIST=2, FVF 0x1c4) via slot 0x64; Jupiter static d3d_DrawLineSystem(Params,pObject).', 'medium', 'jupiter'),
        ('1002421e', 'guess_ModelDraw::DrawModelBox', 'func', 'drawmodel', 'Draws a wireframe box (12 edges as D3DPT_LINELIST via 10024427) of the model dims with ZWRITE/ZENABLE off; called from 1002476b when g_ModelBoxes (100584d0); Jupiter modeldebug.cpp NModelDebug::DrawModelBox is the descendant.', 'low', 'invented'),
        ('10024427', 'd3d_DrawLine', 'func', 'drawmodel', '(const LTVector&,const LTVector&,color): transforms both points by DAT_10055e54, clips (100161e0, mask 0x3f), projects (10008895) and DrawPrimitive(D3DPT_LINELIST,2 verts, FVF 0x1c4); matches Jupiter d3d_draw.h d3d_DrawLine(src,dest,color) signature; only caller is 1002421e.', 'medium', 'jupiter'),
        ('100244b3', 'guess_ModelDraw::BeginModelDraw', 'func', 'drawmodel', 'Saves D3DRS_FILLMODE (8) into DAT_10068030 and sets WIREFRAME(2) when this+0x898 flag 0x10; decides this+0x4c8 (texturing) from g_TextureModels (10048750) and hook flag bit0; reads ALPHABLENDENABLE; out arg = alpha-blended flag; callers 10004270/10024c8b.', 'low', 'invented'),
        ('10024589', 'guess_ModelDraw::SetPieceTexture', 'func', 'drawmodel', '(this,iSkin<4): binds ModelInstance skin texture (inst+0x1c0+4*i) through 100079e4 if g_ModelTexture (10067bf0) else disables stage; also sets stage-1 states when this+0x30; caller 10004270 (piece loop).', 'low', 'invented'),
        ('100246b7', 'guess_SaveAndSetAdditiveStage1', 'func', 'drawmodel', 'GetTextureStageState(1,COLOROP) and (1,ADDRESS) into param, then TSS(1,COLOROP)=7 (D3DTOP_ADD), COLORARG1=2 (TEXTURE), COLORARG2=1 (CURRENT), ADDRESS=3 (CLAMP); DAT_10067be8=7.', 'low', 'invented'),
        ('1002473b', 'guess_RestoreStage1TextureStates', 'func', 'drawmodel', 'Restores TSS(1,COLOROP) and TSS(1,ADDRESS) from the two saved values written by 100246b7.', 'low', 'invented'),
        ('1002476b', 'guess_ModelDraw::DrawModel', 'func', 'drawmodel', 'Central model draw (this = ModelDraw): clears piece flag bytes, sets stage states, chooses piece draw callbacks (0x10001370/90/13e0 families) via 10024c8b/100045a0, then FLAG_SHADOW (this+0x898 &2) -> 100252c6 DrawModelShadows, g_ModelBoxes -> 1002421e, FLAG_REALLYCLOSE (&0x40) -> restore near-Z DAT_10055d80=DAT_10055cb4.', 'low', 'invented'),
        ('10024c8b', 'guess_ModelDraw::DrawPieces', 'func', 'drawmodel', 'Stores piece callbacks at this+0x5f4/+0x5ec, this+0x4c4=1, runs 100244b3 (states), optionally 10005700, 100045a0 (pick/run draw callbacks), then 10024cd7.', 'low', 'invented'),
        ('10024cd7', 'guess_RestoreFillMode', 'func', 'drawmodel', 'SetRenderState(D3DRS_FILLMODE=8, DAT_10068030), restoring the value saved by 100244b3.', 'low', 'invented'),
        ('10024ceb', 'd3d_ProcessModel', 'func', 'drawmodel', 'g_ObjectHandlers[OT_MODEL=1].m_ProcessObjectFn (1004ba9c); alpha(+0x97)!=255 -> VisibleSet+0x164 (VS_MODELS_TRANSLUCENT), else Flags2 bit1 (FLAG2_CHROMAKEY) -> +0x184 (VS_MODELS_CHROMAKEY) else +0x144 (VS_MODELS), via BaseObjectSet::Add.', 'high', 'jupiter'),
        ('10024d22', 'd3d_DrawSolidModels', 'func', 'drawmodel', 'If g_DrawModels (10048778) and VS_MODELS (+0x144) non-empty: SetRenderState SRCBLEND=5/DESTBLEND=6, stage-1 TSS, BaseObjectSet::Draw(set,g_ViewParams,1000b528) then restore; Jupiter d3d_DrawSolidModels (Talon draws immediately, no piece list).', 'medium', 'jupiter'),
        ('10024dc0', 'guess_d3d_DrawChromakeyModels', 'func', 'drawmodel', 'Same as d3d_DrawSolidModels but for the chromakey set VS_MODELS_CHROMAKEY (+0x184); Talon only (Jupiter dropped the set).', 'low', 'invented'),
        ('10024deb', 'd3d_QueueTranslucentModels', 'func', 'drawmodel', 'If g_DrawModels: for every object of VS_MODELS_TRANSLUCENT (+0x164, count +0x168) ObjectDrawList::Add(g_pTransObjList, obj, 10024e2e); matches Jupiter d3d_QueueTranslucentModels and its slot in d3d_FlushObjectQueues.', 'high', 'jupiter'),
        ('10024e2e', 'd3d_DrawTranslucentModel', 'func', 'drawmodel', 'Draw callback of the sorted list: disables stage 1, d3d_GetBlendStates (10024f8c), sets SRCBLEND/DESTBLEND/FOGENABLE/FOGCOLOR from them, draws the model (1000b528), restores; Jupiter static d3d_DrawTranslucentModel(Params,obj).', 'medium', 'jupiter'),
        ('10024f8c', 'd3d_GetBlendStates', 'func', 'drawmodel', 'GetRenderState(FOGCOLOR 0x22, FOGENABLE 0x1c); FLAG_FOGDISABLE(0x80, non-model) clears fog; Flags2&4 (FLAG2_ADDITIVE) -> ONE/ONE fogcolor 0, Flags2&8 (FLAG2_MULTIPLY) -> ZERO/SRCCOLOR fogcolor -1, else SRCALPHA/INVSRCALPHA: identical to Jupiter d3d_draw.h d3d_GetBlendStates(pObject,&src,&dst,&fog,&fogcolor).', 'high', 'jupiter'),
        ('10026009', 'guess_BuildPlanarShadowMatrix', 'func', 'drawmodelshadows', "Builds the 4x4 planar projection ('shadow') matrix from light position (3 floats), plane normal (3) and plane dist: m00 = (n.L-d) - nx*Lx, m03 = d*Lx ... (D3DXMatrixShadow-style); used by 100252c6.", 'low', 'invented'),
        ('10025078', 'guess_ModelDraw::DrawShadowOnPoly', 'func', 'drawmodelshadows', "(ShadowLightInfo*, WorldPoly*): copies poly verts (<=0x80 else 'Error: vertex buffer overflow'), offsets along the poly normal by ModelShadowOffset (_DAT_10069494), clips against the 6 info frustum planes (info+0xa0, 100260ce), sets vertex alpha to ModelShadowAlpha (DAT_10069040), tu/tv from two info matrix rows, DrawPrimitive fan; called per poly from 100252c6.", 'low', 'invented'),
        ('100252c6', 'ModelDraw::DrawModelShadows', 'func', 'drawmodelshadows', 'nShadows=min(8,g_MaxModelShadows 1004876c), <1 -> return; builds per-light ShadowLightInfo (projection centre/plane, window corners, 6 frustum planes) exactly as Jupiter drawmodelshadows.cpp ModelDraw::DrawModelShadows; g_CV_ModelShadowProj (10069060) set -> 1002701e (projected-texture path); called from 1002476b when FLAG_SHADOW.', 'high', 'jupiter'),
        ('100260ce', 'guess_ClipPolyToPlane_Vertex36', 'func', 'drawmodelshadows', 'Jupiter polyclip.h body (bInside[] = DAT_10094440, nInside, pPrev/pCur loop, CLIPTEST=10026300, DOCLIP=10026343, ClipExtra=100261f9) for 0x24-byte vertices against one plane; returns false when all outside.', 'low', 'invented'),
        ('100261f9', 'guess_Vertex36_ClipExtra', 'func', 'drawmodelshadows', 'T::ClipExtra(pPrev,pCur,pOut,t) of polyclip.h: lerps +0x18/+0x1c/+0x20 floats and rounds the colour bytes +0x10..+0x13 and +0x17 for a 0x24-byte vertex.', 'low', 'invented'),
        ('10026300', 'guess_ClipPlaneTest', 'func', 'drawmodelshadows', 'CLIPTEST macro as a function: dot(v, plane.xyz) - plane.d > _DAT_100461c0 (epsilon).', 'low', 'invented'),
        ('10026343', 'guess_ClipPlaneIntersect', 'func', 'drawmodelshadows', 'DOCLIP macro as a function: t = d0/(d0-d1) (guarded by epsilons _DAT_100461c8/c4) and out = a + (b-a)*t; returns t in st0.', 'low', 'invented'),
        ('10094440', 'guess_g_bInside', 'data', 'drawmodelshadows', "Int array written by 100260ce per vertex (nInside accumulation) = 'int bInside[50]' of Jupiter polyclip.h turned into a global.", 'low', 'invented'),
        ('10026412', 'guess_ClipShadowPolyToViewport', 'func', 'drawmodelshadows', '(ppVerts,pnVerts,ViewParams*): same signature shape as the TL clipper 1000af16 but for 0x24-byte verts; g_ClipFlags==0 -> transform+project only (1000868d), else transform (10008719), clip with mask (100264ad), project (10008895).', 'low', 'invented'),
        ('100264ad', 'guess_ClipTLPoly_Vertex36', 'func', 'drawmodelshadows', 'Applies the six plane clippers selected by mask bits: &1 100265c9, &4 10026700, &8 10026835, &0x10 10026969, &0x20 10026a9c, &2 10026bd2; ping-pongs between two buffers.', 'low', 'invented'),
        ('100265c9', 'guess_ClipTLPoly_Vertex36_Near', 'func', 'drawmodelshadows', 'Plane clipper for mask bit 1: intersection routine 10001a50 solves z = near plane (DAT_10055d80); loop of polyclip.h shape on 0x24-byte verts.', 'low', 'invented'),
        ('10026700', 'guess_ClipTLPoly_Vertex36_Side4', 'func', 'drawmodelshadows', 'Plane clipper for mask bit 4 (intersection 10001ac0), polyclip.h shape.', 'low', 'invented'),
        ('10026835', 'guess_ClipTLPoly_Vertex36_Side8', 'func', 'drawmodelshadows', 'Plane clipper for mask bit 8 (intersection 10008b58 = y - z plane), polyclip.h shape.', 'low', 'invented'),
        ('10026969', 'guess_ClipTLPoly_Vertex36_Side10', 'func', 'drawmodelshadows', 'Plane clipper for mask bit 0x10 (intersection 10008bb4), polyclip.h shape.', 'low', 'invented'),
        ('10026a9c', 'guess_ClipTLPoly_Vertex36_Side20', 'func', 'drawmodelshadows', 'Plane clipper for mask bit 0x20 (intersection 10008c10), polyclip.h shape.', 'low', 'invented'),
        ('10026bd2', 'guess_ClipTLPoly_Vertex36_Far', 'func', 'drawmodelshadows', 'Plane clipper for mask bit 2: intersection 10008c6e solves z = far plane (DAT_10055d88); polyclip.h shape.', 'low', 'invented'),
        ('10026d6a', 'guess_ModelDraw::DrawShadowOnPolyProjected', 'func', 'drawmodelshadows', 'Variant of 10025078 used by the projected-texture path 1002701e: per-vertex alpha from distance to light (1000e011 magnitude, __ftol), vertex w kept for perspective divide (tu/w, tv/w), same 6-plane clip and fan draw; same overflow message.', 'low', 'invented'),
