        ('1002c560', 'guess_d3d_ClipTestPolyGridTri', 'func', 'drawpolygrid', '(clipFlags, &outFlags, v0, v1, v2): per frustum plane counts verts inside; returns 1 all outside, 2 partial (narrowed flags), 0 all inside; only caller is the polygrid draw loop.', 'low', 'invented'),
        ('1002c840', 'guess_d3d_GenPolyGridEnvMapUVs', 'func', 'drawpolygrid', 'Per-vertex normal from neighbouring signed-byte heights of pGrid->m_Data (+0x1b0, W/H +0x1f8/+0x1fc) then env-map UV via 1001085e into the 0x28-byte TL verts (g_TriVertList); only called when the env map is active; cf. Jupiter GeneratePolyGridVectors.', 'low', 'invented'),
        ('1002cc80', 'guess_d3d_EmptyPreFrame', 'func', 'drawpolygrid', 'Body is a lone ret; used as ObjectHandler PreFrameFn of WORLDMODEL, SPRITE, POLYGRID and LINESYSTEM in g_ObjectHandlers (0x1004baac/bac0/bb10/bb24), so one shared (linker-folded) empty PreFrame.', 'low', 'invented'),
        ('1002cc90', 'd3d_ProcessPolyGrid', 'func', 'drawpolygrid', 'ObjectHandler[OT_POLYGRID=7].m_ProcessObjectFn (0x1004bb14); appends to the VisibleSet set at +0x264 (VS_POLYGRIDS) or prints "Set \'%s\' overflowed" (0x1004b974).', 'high', 'callgraph'),
        ('1002cce0', 'd3d_DrawSolidPolyGrids', 'func', 'drawpolygrid', 'Called from FlushObjectQueues 10028660 after the solid models; if DrawPolyGrids (0x10048758) walks set +0x264, draws polygrids with m_ColorA==255 immediately (1002aff0) and moves translucent ones to set +0x284 (VS_POLYGRIDS_TRANSLUCENT); Jupiter d3d_DrawSolidPolyGrids role.', 'medium', 'jupiter'),
        ('1002cdc0', 'd3d_QueueTranslucentPolyGrids', 'func', 'drawpolygrid', 'Flush-time (10028660) call: if DrawPolyGrids, BaseObjectSet::Draw(set +0x284 VS_POLYGRIDS_TRANSLUCENT, &g_ViewParams, 1002cdf0) which queues each grid into the sorted translucent list = Jupiter d3d_QueueTranslucentPolyGrids.', 'medium', 'jupiter'),
        ('1002cdf0', 'guess_d3d_QueuePolyGridCB', 'func', 'drawpolygrid', 'BaseObjectSet::Draw callback: ObjectDrawList::Add(g_TransObjList 0x1006b934, pObj, d3d_DrawPolyGrid 1002aff0) (10028ba0 draws immediately when DrawSorted is off).', 'low', 'invented'),
        ('1002ce10', 'guess_d3d_InitPolyGridDraw', 'func', 'drawpolygrid', 'ObjectHandler[OT_POLYGRID].m_ModuleInit (0x1004bb04): zeroes g_TriVertList/g_TriVertListSize and the index list pointer/size.', 'low', 'invented'),
        ('1002ce30', 'd3d_TermPolyGridDraw', 'func', 'drawpolygrid', 'ObjectHandler[OT_POLYGRID].m_ModuleTerm (0x1004bb08): dfree(g_TriVertList) and the index list, zero pointers and sizes = Jupiter d3d_TermPolyGridDraw.', 'high', 'jupiter'),
        ('10070850', 'g_TriVertList', 'data', 'drawpolygrid', 'Vertex buffer reallocated in d3d_DrawPolyGrid when W*H exceeds g_TriVertListSize (dalloc(n*0x28)) and freed in Term; Jupiter drawpolygrid.cpp static g_TriVertList.', 'medium', 'jupiter'),
        ('10070448', 'g_TriVertListSize', 'data', 'drawpolygrid', 'Capacity (in vertices here) compared with W*H in d3d_DrawPolyGrid before reallocating g_TriVertList; Jupiter static g_TriVertListSize.', 'medium', 'jupiter'),
        ('10070858', 'guess_g_TriIndexList', 'data', 'drawpolygrid', "dalloc'd (m_nIndices*2 bytes) 16-bit index scratch for the clipped-triangle path, freed by d3d_TermPolyGridDraw.", 'low', 'invented'),
