        ('1002ce70', 'LTVector::operator+', 'func', 'ltvector', 'Out-of-line copy of SDK ltvector.h _CVector<float>::operator+(const _CVector v) const (this, hidden ret, v passed by value as 3 floats); mangled ??H?$_CVector@M@@QBE?AV0@V0@@Z.', 'medium', 'exe-decomp'),
        ('1002cec0', 'LTVector::operator*', 'func', 'ltvector', 'Out-of-line copy of SDK ltvector.h _CVector<float>::operator*(T v) const: (this, hidden ret, float s) -> (x*s,y*s,z*s); mangled ??D?$_CVector@M@@QBE?AV0@M@Z.', 'medium', 'exe-decomp'),
        ('1002cf10', 'guess_d3d_ProjectPolyGridVerts', 'func', 'drawpolygrid', 'Loops n 0x28-byte TL verts: rhw=1/(m3.v), x,y,z projected with the 4x4 at g_ViewParams+0x19c (0x10055e94..); called by the polygrid draw before DrawIndexedPrimitive.', 'low', 'invented'),
        ('1002d07c', 'guess_d3d_PortalFileCommand', 'func', '', "RenderCommand 1001b8a0 calls it with argv[1] right after matching the 'PortalFile' command (0x1004b128); body is xor eax,eax/ret (release stub). ICF-folded with CRT __matherr (also called by 1003ded2/10042613), hence the lead's __matherr label.", 'low', 'invented'),
        ('1002d080', 'guess_StaticInit_Empty_1002d080', 'func', 'drawsky', 'Static-init table entry (0x1004830c) whose body is a lone ret (global with an empty ctor); first initialiser of the sky TU after the portal-stub TU.', 'low', 'invented'),
        ('1002d090', 'guess_StaticInit_g_SkyParams', 'func', 'drawsky', 'Static-init table entry that zeroes 4 dwords at 0x100739d4 = g_SkyParams(0x100739b8)+0x1c, i.e. the LTRect m_Rect that follows the 0x1c-byte ViewBoxDef of ViewParams (Jupiter layout).', 'low', 'invented'),
        ('100739b8', 'g_SkyParams', 'data', 'drawsky', 'ViewParams filled by d3d_InitFrustum2 (1000f72b) in 1002d4c0 and passed as Params to d3d_DrawSprite 1002d660 by d3d_DrawSkyObjects 10019691; Jupiter drawsky.cpp SkyParams (local there, global here).', 'medium', 'jupiter'),
        ('1002d0d0', 'guess_d3d_ComputeSkyExtents', 'func', 'drawsky', "Projects every visible sky-portal poly (VisibleSet +0x2c/+0x3c, or the world's list at +0x1a0/+0x1a4 when cvar AllSkyPortals 0x10073990) into screen min/max and returns true only if both spans exceed 0.9 (Jupiter d3d_renderworld ExtendSkyBounds + the '> 0.9f' test).", 'low', 'invented'),
        ('1002d4c0', 'd3d_DrawSky', 'func', 'drawsky', 'Gated by cvars DrawSky 0x10048748 and EnableSky 0x1004874c and sceneDesc m_nSkyObjects (+0xb8): calls 1002d0d0, d3d_InitViewBox2(0.01,...,minX,minY,maxX,maxY), d3d_InitFrustum2 with SkyScale (0x10048728) x3 then d3d_DrawSkyObjects 10019691; same body as Jupiter drawsky.cpp d3d_DrawSkyExtents.', 'medium', 'jupiter'),
        ('100739b4', 'g_SkyMinX', 'data', 'drawsky', 'Min of the projected x (first matrix row) in 1002d0d0, passed as the minX arg to d3d_InitViewBox2 in 1002d4c0; Jupiter drawsky.cpp g_SkyMinX.', 'high', 'jupiter'),
        ('100739b0', 'g_SkyMinY', 'data', 'drawsky', 'Min of the projected y in 1002d0d0, the minY arg of d3d_InitViewBox2; Jupiter g_SkyMinY.', 'high', 'jupiter'),
