        ('1002d640', 'guess_StaticInit_Empty_1002d640', 'func', 'drawsprite', 'Static-init table entry (0x10048318) whose body is a lone ret; first initialiser of the sprite TU (follows d3d_DrawSky 1002d4c0).', 'low', 'invented'),
        ('1002d650', 'guess_StaticInit_Empty_1002d650', 'func', 'drawsprite', 'Static-init table entry (0x1004831c) whose body is a lone ret; second initialiser of the sprite TU.', 'low', 'invented'),
        ('1002d660', 'd3d_DrawSprite', 'func', 'drawsprite', 'Jupiter drawsprite.cpp d3d_DrawSprite(Params, LTObject*): SpriteInstance +0x1b4 m_pCurAnim/+0x1b8 m_pCurFrame/m_pTex checks, saves/sets SRCBLEND/DESTBLEND/FOGENABLE/FOGCOLOR (rs 0x13/0x14/0x1c/0x22) then branches on FLAG_ROTATEABLESPRITE (flags&8) to 1002e310 else 1002d860.', 'high', 'jupiter'),
        ('1002d860', 'd3d_DrawSprite_NonRotatable', 'func', 'drawsprite', "Jupiter's static d3d_DrawSprite(Params, SpriteInstance*, SharedTexture*) overload (name disambiguated): REALLYCLOSE basis (flags&0x40), FLAG_GLOWSPRITE scale between 10 and 500 units (0x10046498/9c) with 0.1..2.0 (0x100464a0/a4), SPRITEBIAS -20.0 (0x100464a8), TROTATE UV rotation.", 'medium', 'jupiter'),
        ('1002e310', 'd3d_DrawRotatableSprite', 'func', 'drawsprite', 'Jupiter d3d_DrawRotatableSprite: builds the 4 quad verts from m_Rotation/m_Scale, clips against m_ClipperPoly (+0x1c4) via 1002ebb0 and applies the SPRITEBIAS Z shift (-20.0) via 1002f010; only caller is d3d_DrawSprite 1002d660.', 'high', 'jupiter'),
        ('1002e9f0', 'd3d_ProcessSprite', 'func', 'drawsprite', "ObjectHandler[OT_SPRITE=3].m_ProcessObjectFn (0x1004bac4): FLAG_SPRITE_NOZ (flags&0x10) picks set +0x1c4 (VS_SPRITES_NOZ) else +0x1a4 (VS_SPRITES), same as Jupiter d3d_ProcessSprite, or prints 'Set overflowed'.", 'high', 'callgraph'),
        ('1002ea40', 'd3d_QueueTranslucentSprites', 'func', 'drawsprite', 'Flush-time (10028660): if DrawSprites (0x10048754) runs BaseObjectSet::Draw over set +0x1a4 (VS_SPRITES) with callback 1002ea70 that queues into the sorted list = Jupiter d3d_QueueTranslucentSprites (no Params/list args here).', 'medium', 'jupiter'),
        ('1002ea70', 'guess_d3d_QueueSpriteCB', 'func', 'drawsprite', 'BaseObjectSet::Draw callback: ObjectDrawList::Add(g_TransObjList, pObj, d3d_DrawSprite 1002d660).', 'low', 'invented'),
        ('1002ea90', 'd3d_DrawNoZSprites', 'func', 'drawsprite', 'Last call of FlushObjectQueues: if DrawSprites and set +0x1c8 (VS_SPRITES_NOZ count) != 0, SetRenderState(ZENABLE=7, 0), Draw(set +0x1c4, d3d_DrawSprite), restore ZENABLE; identical to Jupiter d3d_DrawNoZSprites.', 'high', 'jupiter'),
        ('1002eaf0', 'guess_d3d_ProjectSpriteVerts', 'func', 'drawsprite', '(verts, n, matrix): x,y,z = (M*v)/w per 0x20-byte TL vertex (w=1/(m12*x+m13*y+m14*z+m15)); only caller is d3d_DrawRotatableSprite.', 'low', 'invented'),
        ('1002ebb0', 'd3d_ClipSprite', 'func', 'drawsprite', 'Jupiter d3d_ClipSprite(pInstance, hPoly, ppPoints, pnPoints, pOut): needs the world, HPOLY high word indexes the BSP list (+0x18c/+0x190), returns false if viewer dist to the poly plane <= 0.01 (0x100463dc), then clips against each poly edge plane (polyclip.h).', 'high', 'jupiter'),
        ('1002f010', 'guess_d3d_ProjectBiasedSpriteVerts', 'func', 'drawsprite', 'Transforms the quad by the object matrix, clips with the g_ClipFlags clip-flag cascade, then projects with z pushed toward the camera by a bias (-20.0 passed from 1002e310 for FLAG_SPRITEBIAS; Jupiter SPRITE_POSITION_ZBIAS).', 'low', 'invented'),
        ('1002f350', 'guess_StaticInit_Empty_1002f350', 'func', 'drawworldmodel', 'Static-init table entry (0x10048324) whose body is a lone ret, directly after the DrawWorldModels cvar initialiser at the start of the world-model TU.', 'low', 'invented'),
        ('1002f360', 'd3d_ProcessWorldModel', 'func', 'drawworldmodel', 'ObjectHandler[OT_WORLDMODEL=2] and [OT_CONTAINER=9].m_ProcessObjectFn (0x1004bab0/0x1004bb3c); first poly surface flags SURF_TRANSPARENT(8) -> set +0x204 (translucent), else FLAG2_CHROMAKEY(2) -> +0x224, else +0x1e4 (VS_WORLDMODELS*).', 'high', 'callgraph'),
        ('1002f440', 'guess_d3d_DrawWorldModelPolys', 'func', 'drawworldmodel', '(pObj, WorldPoly** polies, n, viewPosInModel, clipFlags): skips polys facing away and SURF_INVISIBLE(4), then dispatches by Surface (+0x2c, flags +0x30): no texture -> DAT_10058cd8, SURF_LIGHTMAP(0x80) -> DAT_10058c24, SURF_PANNINGSKY(0x8000) -> DAT_1005a304 else DAT_100587e8; relights polys flagged WPF_RELIGHT first.', 'low', 'invented'),
        ('1002f780', 'guess_d3d_RelightWorldPoly', 'func', 'drawworldmodel', "(world, poly): zeroes the vertex RGB bytes (+0x14 of the 0x18-byte SPolyVertex) then for each WorldPoly m_pLMAnimRefs (+0xc/+0x10) indexes the world's 0x60-byte light-anim table and adds anim colours with the saturating-add/multiply tables (same math as 100185a0); engine twin is MainWorld::UpdateLightAnimPolies / WPF_RELIGHT.", 'low', 'invented'),
        ('1002fa50', 'd3d_DrawSolidWorldModels', 'func', 'drawworldmodel', 'First draw call of FlushObjectQueues 10028660: if DrawWorldModels (0x100752b0) and set +0x1e8 (VS_WORLDMODELS count) != 0, BaseObjectSet::Draw(set +0x1e4, d3d_DrawSolidWorldModel 1002fa80) = Jupiter d3d_DrawSolidWorldModels.', 'medium', 'jupiter'),
        ('1002fa80', 'd3d_DrawSolidWorldModel', 'func', 'drawworldmodel', 'Jupiter d3d_DrawSolidWorldModel(Params, pObj): bsp bound-radius frustum reject, fog = !(FLAG_FOGDISABLE), saves ViewParams matrices, MatMul by WorldModelInstance m_Transform (+0x1f8), view pos through m_BackTransform (+0x238), draws the BSP polys (1002f440), restores matrices and fog.', 'high', 'jupiter'),
        ('1002fed0', 'guess_d3d_DrawChromakeyWorldModels', 'func', 'drawworldmodel', 'Flush-time call: if DrawWorldModels and set +0x228 (VS_WORLDMODELS_CHROMAKEY count) != 0, Draw(set +0x224, 1002fa80); the chromakey sibling of d3d_DrawSolidWorldModels.', 'low', 'invented'),
        ('1002ff00', 'd3d_QueueTranslucentWorldModels', 'func', 'drawworldmodel', 'Walks VS_WORLDMODELS_TRANSLUCENT (+0x204): SURF_ADDITIVE(0x80000) models are collected in a 0x400-entry stack array and queued with 10030ad0 after the others, normal ones are queued with 10030070 into g_TransObjList (10028ba0); Jupiter d3d_QueueTranslucentWorldModels role.', 'medium', 'jupiter'),
        ('10030070', 'd3d_DrawTranslucentWorldModel', 'func', 'drawworldmodel', 'Sorted-list callback (Params,pObj) queued by 1002ff00: same object colour/fog/matrix prologue as 1002fa80, then BSP back-to-front traversal (GetRootNode vtable+4, node flags&3, plane side from the view pos) drawing each node poly with 10030370; Jupiter d3d_DrawTranslucentWorldModel role.', 'medium', 'jupiter'),
        ('10030370', 'guess_d3d_DrawTranslucentWorldPoly', 'func', 'drawworldmodel', "Single-poly translucent draw: relights if WPF_RELIGHT, per-vertex colour with dynamic lights from poly+0x30 (DynamicLight m_LightRadius +0x1b0), env-map UVs, clip, DrawPrimitive FAN FVF 0x2c4; 'Error: vertex buffer overflow' (0x1004842c) above 0x80 verts; only caller 10030070.", 'low', 'invented'),
        ('10030ad0', 'guess_d3d_DrawAdditiveWorldModel', 'func', 'drawworldmodel', 'Queued by 1002ff00 for SURF_ADDITIVE(1<<19) models: SetRenderState SRCBLEND(0x13)=ONE, DESTBLEND(0x14)=ONE, FOGCOLOR(0x22)=0, calls 10030070, restores (Jupiter folds this into d3d_DrawTranslucentWorldModel with FLAG2_ADDITIVE).', 'low', 'invented'),
